-- Generated from the verified pilot (FPT, HPG, VNM; FY2022-2025). Do not edit by hand.
-- Run as an administrator with CURRENT_SCHEMA set to the owner schema (db/install.sh).
-- Loads through the real packages so validation, snapshots and lineage are rebuilt, not copied.
WHENEVER SQLERROR EXIT SQL.SQLCODE ROLLBACK
SET DEFINE OFF
SET SERVEROUTPUT ON
MERGE INTO companies t USING (SELECT 'FPT' k, 'Công ty Cổ phần FPT' n FROM dual) s ON (t.company_key = s.k) WHEN NOT MATCHED THEN INSERT (company_key, company_name) VALUES (s.k, s.n);
MERGE INTO securities t USING (SELECT company_id FROM companies WHERE company_key = 'FPT') s ON (t.symbol = 'FPT' AND t.exchange_code = 'HOSE') WHEN NOT MATCHED THEN INSERT (company_id, symbol, exchange_code) VALUES (s.company_id, 'FPT', 'HOSE');
MERGE INTO companies t USING (SELECT 'HPG' k, 'Công ty Cổ phần Tập đoàn Hòa Phát' n FROM dual) s ON (t.company_key = s.k) WHEN NOT MATCHED THEN INSERT (company_key, company_name) VALUES (s.k, s.n);
MERGE INTO securities t USING (SELECT company_id FROM companies WHERE company_key = 'HPG') s ON (t.symbol = 'HPG' AND t.exchange_code = 'HOSE') WHEN NOT MATCHED THEN INSERT (company_id, symbol, exchange_code) VALUES (s.company_id, 'HPG', 'HOSE');
MERGE INTO companies t USING (SELECT 'VNM' k, 'Công ty Cổ phần Sữa Việt Nam' n FROM dual) s ON (t.company_key = s.k) WHEN NOT MATCHED THEN INSERT (company_key, company_name) VALUES (s.k, s.n);
MERGE INTO securities t USING (SELECT company_id FROM companies WHERE company_key = 'VNM') s ON (t.symbol = 'VNM' AND t.exchange_code = 'HOSE') WHEN NOT MATCHED THEN INSERT (company_id, symbol, exchange_code) VALUES (s.company_id, 'VNM', 'HOSE');
MERGE INTO financial_items t USING (SELECT 'revenue' k FROM dual) s ON (t.item_code = s.k) WHEN NOT MATCHED THEN INSERT (item_code, item_name, statement_kind, value_kind) VALUES (s.k, 'revenue', 'IS', 'MONEY');
MERGE INTO financial_items t USING (SELECT 'gross_profit' k FROM dual) s ON (t.item_code = s.k) WHEN NOT MATCHED THEN INSERT (item_code, item_name, statement_kind, value_kind) VALUES (s.k, 'gross_profit', 'IS', 'MONEY');
MERGE INTO financial_items t USING (SELECT 'net_income' k FROM dual) s ON (t.item_code = s.k) WHEN NOT MATCHED THEN INSERT (item_code, item_name, statement_kind, value_kind) VALUES (s.k, 'net_income', 'IS', 'MONEY');
MERGE INTO financial_items t USING (SELECT 'parent_net_income' k FROM dual) s ON (t.item_code = s.k) WHEN NOT MATCHED THEN INSERT (item_code, item_name, statement_kind, value_kind) VALUES (s.k, 'parent_net_income', 'IS', 'MONEY');
MERGE INTO financial_items t USING (SELECT 'current_assets' k FROM dual) s ON (t.item_code = s.k) WHEN NOT MATCHED THEN INSERT (item_code, item_name, statement_kind, value_kind) VALUES (s.k, 'current_assets', 'BS', 'MONEY');
MERGE INTO financial_items t USING (SELECT 'assets' k FROM dual) s ON (t.item_code = s.k) WHEN NOT MATCHED THEN INSERT (item_code, item_name, statement_kind, value_kind) VALUES (s.k, 'assets', 'BS', 'MONEY');
MERGE INTO financial_items t USING (SELECT 'liabilities' k FROM dual) s ON (t.item_code = s.k) WHEN NOT MATCHED THEN INSERT (item_code, item_name, statement_kind, value_kind) VALUES (s.k, 'liabilities', 'BS', 'MONEY');
MERGE INTO financial_items t USING (SELECT 'current_liabilities' k FROM dual) s ON (t.item_code = s.k) WHEN NOT MATCHED THEN INSERT (item_code, item_name, statement_kind, value_kind) VALUES (s.k, 'current_liabilities', 'BS', 'MONEY');
MERGE INTO financial_items t USING (SELECT 'equity' k FROM dual) s ON (t.item_code = s.k) WHEN NOT MATCHED THEN INSERT (item_code, item_name, statement_kind, value_kind) VALUES (s.k, 'equity', 'BS', 'MONEY');
MERGE INTO financial_items t USING (SELECT 'funding_total' k FROM dual) s ON (t.item_code = s.k) WHEN NOT MATCHED THEN INSERT (item_code, item_name, statement_kind, value_kind) VALUES (s.k, 'funding_total', 'BS', 'MONEY');
MERGE INTO financial_items t USING (SELECT 'cfo' k FROM dual) s ON (t.item_code = s.k) WHEN NOT MATCHED THEN INSERT (item_code, item_name, statement_kind, value_kind) VALUES (s.k, 'cfo', 'CF', 'MONEY');
COMMIT;
